import numpy as np, csv, collections, math, json
C=2.955
man=list(csv.DictReader(open('manifest.csv')))
res=list(csv.DictReader(open('results.csv')))
key=lambda r:(float(r['lr']),int(r['batch']),r['sched'],float(r['init_scale']),r['precision'])
ml=collections.Counter(key(r) for r in man)
rl=collections.defaultdict(list)
for r in res: rl[key(r)].append(float(r['val_loss']))
cells=sorted(k for k in ml if len(rl[k])>0)
data={k:np.array(rl[k]) for k in cells}

from math import erf, sqrt
def Phi(z): return 0.5*(1+erf(z/sqrt(2)))
def phi(z): return math.exp(-0.5*z*z)/sqrt(2*math.pi)

def nll_cell(mu,sig,x):
    z=(C-mu)/sig
    return len(x)*(math.log(sig)+math.log(Phi(z))) + np.sum((x-mu)**2)/(2*sig**2)

def fit_mu(x,sig,mu0):
    # maximize truncated normal likelihood over mu with Newton / golden
    lo,hi=mu0-0.5,mu0+0.5
    for _ in range(100):
        m1=lo+(hi-lo)*0.382; m2=lo+(hi-lo)*0.618
        if nll_cell(m1,sig,x)<nll_cell(m2,sig,x): hi=m2
        else: lo=m1
    return 0.5*(lo+hi)

def total(sig):
    mus={k:fit_mu(data[k],sig,data[k].mean()) for k in cells}
    return sum(nll_cell(mus[k],sig,data[k]) for k in cells), mus

lo,hi=0.05,0.15
for _ in range(60):
    s1=lo+(hi-lo)*0.382; s2=lo+(hi-lo)*0.618
    if total(s1)[0]<total(s2)[0]: hi=s2
    else: lo=s1
sig=0.5*(lo+hi); _,mus=total(sig)
print('sigma',sig)
out={'sigma':sig,'mus':{str(k):v for k,v in mus.items()}}
for k in cells:
    z=(C-mus[k])/sig
    n=len(data[k]); surv=Phi(z)
    print(k, n, 'mu=%.4f'%mus[k], 'Pguard=%.3f'%(1-surv), 'implied 1-p_pre=%.3f'%(n/(2000*surv)))
json.dump(out,open('fit.json','w'))
